<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('payroll.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['_action']??'create'; if($action==='create'){try{db()->beginTransaction(); $start=$_POST['period_start'];$end=$_POST['period_end']; q('INSERT INTO payroll_runs(branch_id,period_start,period_end,status,notes,created_by,created_at) VALUES(?,?,?,"draft",?,?,NOW())',[$bid,$start,$end,trim($_POST['notes']??''),$_SESSION['user_id']]); $run=(int)db()->lastInsertId(); foreach(all('SELECT * FROM staff WHERE branch_id=? AND status="active"',[$bid]) as $st){$comm=(float)scalar('SELECT COALESCE(SUM(commission_amount),0) FROM commissions WHERE branch_id=? AND staff_id=? AND status="unpaid" AND DATE(created_at) BETWEEN ? AND ?',[$bid,$st['id'],$start,$end]); $bonus=(float)($_POST['bonus_'.$st['id']]??0);$ded=(float)($_POST['deductions_'.$st['id']]??0);$adv=(float)($_POST['advance_'.$st['id']]??0);$net=(float)$st['salary']+$comm+$bonus-$ded-$adv; q('INSERT INTO payroll_items(payroll_run_id,staff_id,basic_salary,commission_amount,bonus,deductions,advance_amount,net_salary) VALUES(?,?,?,?,?,?,?,?)',[$run,$st['id'],$st['salary'],$comm,$bonus,$ded,$adv,$net]);} audit('create','payroll_runs',$run); db()->commit(); flash('success','Payroll run created.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/payroll.php'); }
 if($action==='approve'||$action==='pay'){ $id=(int)$_POST['id']; if($action==='approve') q('UPDATE payroll_runs SET status="approved",approved_by=? WHERE id=? AND branch_id=?',[$_SESSION['user_id'],$id,$bid]); else {q('UPDATE payroll_runs SET status="paid",paid_at=NOW() WHERE id=? AND branch_id=?',[$id,$bid]); q('UPDATE commissions c JOIN payroll_items pi ON pi.staff_id=c.staff_id SET c.status="paid" WHERE pi.payroll_run_id=? AND c.status="unpaid"',[$id]);} audit('update','payroll_runs',$id,['action'=>$action]); flash('success','Payroll updated.'); redirect('modules/payroll.php?view='.$id);} }
$view=(int)($_GET['view']??0); $run=$view?one('SELECT * FROM payroll_runs WHERE id=? AND branch_id=?',[$view,$bid]):null; $title='Payroll'; $subtitle='Salary, commission, bonus, deductions, advance and net salary.'; include dirname(__DIR__).'/includes/header.php';?><div class="toolbar"><a class="btn" href="?new=1">+ New Payroll Run</a></div><?php if(isset($_GET['new'])):$staff=all('SELECT * FROM staff WHERE branch_id=? AND status="active" ORDER BY full_name',[$bid]);?><section class="card"><h2>Create Payroll</h2><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="create"><div class="form-grid"><div class="form-group"><label>Period Start</label><input type="date" name="period_start" value="<?=e(date('Y-m-01'))?>"></div><div class="form-group"><label>Period End</label><input type="date" name="period_end" value="<?=e(today())?>"></div><div class="form-group full"><label>Notes</label><input name="notes"></div></div><h3>Optional Adjustments</h3><table><thead><tr><th>Staff</th><th>Bonus</th><th>Deductions</th><th>Advance</th></tr></thead><tbody><?php foreach($staff as $s):?><tr><td><?=e($s['full_name'])?></td><td><input type="number" step="0.01" name="bonus_<?=e($s['id'])?>" value="0"></td><td><input type="number" step="0.01" name="deductions_<?=e($s['id'])?>" value="0"></td><td><input type="number" step="0.01" name="advance_<?=e($s['id'])?>" value="0"></td></tr><?php endforeach;?></tbody></table><button class="btn">Create Payroll</button></form></section><?php endif; if($run):$items=all('SELECT pi.*,st.full_name FROM payroll_items pi JOIN staff st ON st.id=pi.staff_id WHERE pi.payroll_run_id=?',[$run['id']]);?><section class="card"><h2>Payroll <?=e($run['period_start'])?> to <?=e($run['period_end'])?></h2><p>Status: <strong><?=e($run['status'])?></strong></p><table><thead><tr><th>Staff</th><th>Salary</th><th>Commission</th><th>Bonus</th><th>Deductions</th><th>Advance</th><th>Net</th></tr></thead><tbody><?php $total=0; foreach($items as $it):$total+=(float)$it['net_salary'];?><tr><td><?=e($it['full_name'])?></td><td><?=money($it['basic_salary'])?></td><td><?=money($it['commission_amount'])?></td><td><?=money($it['bonus'])?></td><td><?=money($it['deductions'])?></td><td><?=money($it['advance_amount'])?></td><td><?=money($it['net_salary'])?></td></tr><?php endforeach;?><tr><th colspan="6">Total</th><th><?=money($total)?></th></tr></tbody></table><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($run['id'])?>"><?php if($run['status']==='draft'):?><button name="_action" value="approve" class="btn secondary">Approve</button><?php endif;if(in_array($run['status'],['draft','approved'])):?><button name="_action" value="pay" class="btn success">Mark Paid</button><?php endif;?></form></section><?php endif; $runs=all('SELECT * FROM payroll_runs WHERE branch_id=? ORDER BY id DESC LIMIT 100',[$bid]);?><div class="table-wrap"><table><thead><tr><th>Period</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($runs as $r):?><tr><td><?=e($r['period_start'])?> to <?=e($r['period_end'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><a class="btn small light" href="?view=<?=e($r['id'])?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>